+        .sub(/\A +/) { |spaces| "&nbsp;" * spaces.size }
+        .gsub(/ {2,}/) { |spaces| ("&nbsp;" * (spaces.size - 1)) + " " }
+    end
+    lines.join("<br />\n")
+  end
